function api_geb(string $state,string $q,string $year,string $project,string $indicator,string $country,int $page,int $perPage):array{ $where=[];$args=[];if($state!=='all'){$where[]='s.state=?';$args[]=$state;}if($q!==''){$where[]='(p.project_code LIKE ? OR p.project_name LIKE ? OR i.code LIKE ? OR i.name LIKE ? OR s.country LIKE ? OR su.name LIKE ?)';for($i=0;$i<6;$i++)$args[]="%{$q}%";}if($year!==''){if(!ctype_digit($year))api_error(400,'Year must be numeric.');$where[]='s.reporting_year=?';$args[]=(int)$year;}if($project!==''){$where[]='p.project_code=?';$args[]=$project;}if($indicator!==''){$where[]='i.code=?';$args[]=$indicator;}if($country!==''){$where[]='s.country=?';$args[]=$country;}$base="FROM submissions s JOIN projects p ON p.id=s.project_id JOIN indicators i ON i.id=s.indicator_id JOIN users su ON su.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id";$w=$where?' WHERE '.implode(' AND ',$where):'';$c=db()->prepare('SELECT COUNT(*) '.$base.$w);$c->execute($args);$total=(int)$c->fetchColumn();$off=($page-1)*$perPage;$sql="SELECT s.id,p.project_code,p.project_name,p.region,p.countries project_countries,i.code indicator_code,i.name indicator_name,i.level indicator_level,i.unit indicator_catalogue_unit,s.reporting_year,s.country,s.reported_value,s.unit,s.disaggregation,s.data_source,s.methodology,s.notes,s.evidence_path,s.state,su.name submitter,su.username submitter_username,su.email submitter_email,r.name reviewer,r.username reviewer_username,r.email reviewer_email,a.name approver,a.username approver_username,a.email approver_email,s.created_at,s.updated_at,s.approved_at,s.auto_generated,s.source_submission_id ".$base.$w." ORDER BY s.updated_at DESC,s.id DESC LIMIT ? OFFSET ?";$st=db()->prepare($sql);$b=$args;$b[]=$perPage;$b[]=$off;$st->execute($b);$data=[];foreach($st->fetchAll() as $r)$data[]=['id'=>(int)$r['id'],'project'=>['code'=>$r['project_code'],'name'=>$r['project_name'],'region'=>$r['region'],'count