function api_sub(string $state,string $q,string $year,string $project,string $indicator,string $country,int $page,int $perPage):array{$where=[];$args=[];if($state!=='all'){$where[]='s.state=?';$args[]=$state;}if($q!==''){$where[]='(p.project_code LIKE ? OR p.project_name LIKE ? OR si.code LIKE ? OR si.name LIKE ? OR s.country LIKE ? OR u.name LIKE ?)';for($i=0;$i<6;$i++)$args[]="%{$q}%";}if($year!==''){if(!ctype_digit($year))api_error(400,'Year must be numeric.');$where[]='s.reporting_year=?';$args[]=(int)$year;}if($project!==''){$where[]='p.project_code=?';$args[]=$project;}if($indicator!==''){$where[]='i.code=?';$args[]=$indicator;}if($country!==''){$where[]='s.country=?';$args[]=$country;}$base="FROM subindicator_submissions s JOIN projects p ON p.id=s.project_id JOIN sub_indicators si ON si.id=s.sub_indicator_id JOIN components c ON c.id=si.component_id LEFT JOIN indicators i ON i.id=s.geb_indicator_id JOIN users u ON u.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id";$w=$where?' WHERE '.implode(' AND ',$where):'';$c=db()->prepare('SELECT COUNT(*) '.$base.$w);$c->execute($args);$total=(int)$c->fetchColumn();$off=($page-1)*$perPage;$sql="SELECT s.id,p.project_code,p.project_name,p.region,p.countries project_countries,c.code component_code,c.name component_name,si.code subindicator_code,si.name subindicator_name,si.indicator_type,si.unit catalogue_unit,i.code geb_code,i.name geb_name,s.reporting_year,s.country,s.reported_value,s.unit,s.result_text,s.disaggregation,s.data_source,s.methodology,s.notes,s.evidence_path,s.state,u.name submitter,u.username submitter_username,u.email submitter_email,r.name reviewer,r.username reviewer_username,r.email reviewer_email,a.name approver,a.username approver_username,a.email approver_email,s.created_at,s.updated_at,s.approved_at ".$base.$w." ORDER BY s.updated_at DESC,s.id DESC LIMIT ? OFFSET ?";$st=db()->prepare($sql);$b=$args;$b[]=$perPage;$b[]=$off;$st->execute($b);$data=[];f